-- Rifts World Book 26: Dinosaur Swamp - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 9 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~252-dinosaur-swamp-npcs.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('tunnel-goblin-leader', 'Tunnel Goblin Leader', NULL, 'Shaman or Earth Wizard', 'rifts', 'Tunnel Goblin', 'Clan leader; shaman or Earth Wizard', NULL, 'Uncertain; presumed Aberrant evil', NULL, '6 feet (1.8 m)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 13, NULL, 'The book prints one block for the leader and the warriors, held whole by the creature row Tunnel Goblins (tunnel-goblins): attributes, bonuses, attacks, natural abilities, clay form and spells. The leader''s own figures there: M.D.C. 6D6+60, P.P.E. P.E. x5 plus 1D6+6 per level, average level 1D6+3, and the Earth Warlock spell list, which only the leader knows.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The head of the Tunnel Goblin clan under the Castle Kingdom ruins in Florida, a head taller than the warriors and the only one who casts elemental (Earth) magic. Not a named person: a role in the clan, recorded here so the Codex lists it beside the book''s other people. Its stat block is the creature row Tunnel Goblins.', 'Rifts World Book 26: Dinosaur Swamp p.113'),
('hirgg', 'Hirgg', 'Hirgg', 'King of the Rat Men (self-proclaimed)', 'rifts', 'Rat Man', '3rd level Vagabond', 3, 'Scrupulous', '22', '5 feet, 6 inches (1.7 m)', '100 lbs (45 kg)', '{"IQ":18,"ME":17,"MA":19,"PS":9,"PP":11,"PE":10,"PB":9,"Spd":20}', 26, 29, NULL, 9, NULL, NULL, NULL, '{"attacks":4,"parry":2,"dodge":2,"roll":3,"pull":2}', 'M.D.C. by body armor only.', '[{"name":"Prowl","pct":35},{"name":"Pick Pockets","pct":42}]', 'Athletics, W.P. Knife, W.P. Energy Pistol.', 'Those of every Rat Man (the creature row Rat Men of Atlanta): nightvision, strong swimming and climbing, keen hearing.', 'None.', 'None.', NULL, NULL, 'Patchwork Juicer plate armor worn down to 23 M.D.C.; Neural Mace; Wilk''s 320 Laser Pistol, fully charged, with two spare E-Clips. He admires the Wilk''s look and wants Wilk''s laser rifles and better M.D.C. armor for himself and his people.', NULL, 'Thin and wiry, but carries himself with a confidence and an edge of anger that read as strength. He makes decisions, gives orders and wants a better future for his people; his lack of fear is what gives the other Rat Men their courage.', 'The Rat Men of Atlanta', 'The Kopar barbarians, who see the Rat Men as rivals and thieves', 'The self-made king of the Rat Men living in the tunnels of ruined Atlanta: a bold, curious natural leader with a vision for his timid people.', 'Rifts World Book 26: Dinosaur Swamp p.122'),
('lyxander', 'Lyxander', 'Lyxander Ekbanio', 'Leader of the Eleytherians', 'rifts', 'True Atlantean', '7th level Headhunter', 7, 'Principled', '81 (looks 21)', '6 feet, 2 inches (1.9 m)', '184 lbs (82.8 kg)', '{"IQ":15,"ME":24,"MA":19,"PS":26,"PP":9,"PE":17,"PB":17,"Spd":19}', 43, 91, NULL, 22, NULL, NULL, NULL, '{"attacks":6,"strike":2,"parry":5,"dodge":5,"damage":11,"roll":3,"pull":3}', 'Damage bonus is to S.D.C. damage. +3 to save vs magic, +4 vs Horror Factor, +1 vs poison, +5 vs psionics and insanity; 55% trust/intimidate, 35% charm/impress. M.D.C. by body armor only. Occupation: resistance leader.', '[{"name":"Language: Atlantean/Greek","pct":98},{"name":"Language: American (British dialect)","pct":98},{"name":"Language: Euro","pct":98},{"name":"Pilot Jet Pack","pct":76},{"name":"History","pct":75}]', 'Hand to Hand: Expert, Boxing, W.P. Energy Rifle, W.P. Energy Pistol, W.P. Sword.', 'Those of every True Atlantean (Rifts World Book Two: Atlantis p.16): Tattoo Magic, sensing vampires and ley lines, ley line phasing, operating dimensional pyramids.', 'Marks of Heritage, given him by a Chiang-Ku dragon rather than his clan; his sword tattoo is a Spartan short sword.', 'None. I.S.P. none.', NULL, NULL, 'Gladiator - Full Environmental Body Armor (70 M.D.C.), red and gold, styled as a Spartan hoplite''s, with an M.D.C. cape (10 M.D.C.); Q2-20 LLG "Infantry Standard" (the Free Quebec laser rifle and grenade launcher), taken while with the Liberated Underground and repainted red and gold.', NULL, 'Driven to the point of obsession by the freeing of Atlantis, which he sees as his destiny. Decisive, resourceful and likable, but so fixed on his goal that others can steer him through it, and deaf to advice he disagrees with; his growing sense of superiority may ruin him and everyone who follows him.', 'Falcone and Oxrik, his advisors; the Eleytherians, fewer than two dozen', 'The Splugorth and the Sunaj; above all Zash-Danzas, the traitor he knew as Ascalus', 'Raised in the Eternal City near Bath by parents who hid that they were exiled Sunaj, and who never told him. He left the Liberated Underground to found the more militant Eleytherians; their first raid was a Sunaj trap, and he now hides in the Atlanta tunnels raising an army to retake Atlantis. A tall, olive-skinned, curly-haired man in a silver circlet.', 'Rifts World Book 26: Dinosaur Swamp p.123-124'),
('falcone', 'Falcone', 'Sir Falcone Maviteyolucas', 'Second in command of the Eleytherians', 'rifts', 'True Atlantean', '5th level Cyber-Knight', 5, 'Scrupulous', '79', '6 feet, 3 inches (1.9 m)', '205 lbs (92.3 kg)', '{"IQ":13,"ME":21,"MA":18,"PS":24,"PP":18,"PE":24,"PB":17,"Spd":23}', 42, 116, 56, 44, NULL, 16, NULL, '{"attacks":6,"initiative":3,"strike":4,"parry":5,"dodge":5,"damage":8,"roll":5,"pull":7,"disarm":2}', 'M.D.C. 56 and A.R. 16 are his Cyber-Armor (main body); body armor on top. +7 to save vs magic, +6 vs Horror Factor, +5 vs poison, +3 vs psionics and insanity. The Cyber-Knight Zen Combat bonuses against technology are not included. Occupation: resistance leader.', '[{"name":"Language: American","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Atlantean/Greek","pct":98},{"name":"Language: Euro","pct":70}]', 'Martial Arts, Cyber-Knight Zen Combat, W.P. Energy Pistol, W.P. Sharpshooting (Energy Pistol), W.P. Sword, W.P. Shield.', 'Those of every True Atlantean (Rifts World Book Two: Atlantis p.16): Tattoo Magic, sensing vampires and ley lines, ley line phasing, operating dimensional pyramids.', 'Marks of Heritage; his sword tattoo is an Egyptian kopesh, which makes him think his clan has ties to Africa.', 'Only the Cyber-Knight Psi-Sword (2D6 M.D.) and Psi-Shield, both a dark blue-white.', NULL, 'Cyber-Armor: A.R. 16, 56 M.D.C. main body.', 'Light Cyber-Knight EBA (35 M.D.C.), dark blue with white trim; two NG-57 Northern Gun Heavy-Duty Ion Blaster pistols in low-slung quick-draw holsters. His habit is to pin a foe down with both pistols while he closes, then finish with Psi-Sword and Psi-Shield.', NULL, 'Showy, noble and adventurous; a childhood of cruelty left him quick to strike at injustice. Proud without being overbearing, he does everything with flair. He dislikes hiding but accepts the need to wait, and fills the time scouting and hunting monsters.', 'Lyxander, his friend and warrior-brother; the Eleytherians', 'Vampires; the Splugorth and the Sunaj', 'A slave and plaything of the vampire lord el Arzon as a boy, freed by vampire hunters from Arzno, one of them a True Atlantean who taught him his tattoos. He became a Cyber-Knight''s squire, then a knight, wandered for decades, and met Lyxander in the Liberated Underground. Dark-skinned and hawk-nosed, with short upright hair.', 'Rifts World Book 26: Dinosaur Swamp p.124-125'),
('oxrik', 'Oxrik', 'Oxrik', 'Advisor to Lyxander', 'rifts', 'True Atlantean', '9th level Mind Melter', 9, 'Anarchist, leaning strongly toward Aberrant', '164', '6 feet, 3 inches (1.9 m)', '160 lbs (72 kg)', '{"IQ":14,"ME":20,"MA":13,"PS":17,"PP":8,"PE":19,"PB":21,"Spd":21}', 46, 70, NULL, 30, 240, NULL, NULL, '{"attacks":6,"strike":1,"parry":2,"dodge":2,"damage":4,"roll":2,"pull":2}', 'Damage bonus is to S.D.C. damage; the book gives six actions per melee round. +4 to save vs magic, +4 vs Horror Factor, +3 vs psionics and insanity, +2 vs poison; 55% charm/impress. M.D.C. by body armor. Occupation: resistance leader.', '[{"name":"Language: Atlantean/Greek","pct":98},{"name":"Language: American","pct":90},{"name":"Language: Euro","pct":90},{"name":"Prowl","pct":67}]', 'Hunting, W.P. Sword, Hand to Hand: Basic.', 'Those of every True Atlantean (Rifts World Book Two: Atlantis p.16): Tattoo Magic, sensing vampires and ley lines, ley line phasing, operating dimensional pyramids.', 'Marks of Heritage; his sword tattoo is a falx, a long thin blade that flexes like a whip.', 'Sensitive: Astral Projection, Clairvoyance, Empathy, Mind Block, Object Read, See Aura, Sense Magic, Sixth Sense, Telepathy. Healing: Bio-Regeneration, Deaden Pain, Exorcism, Induce Sleep. Physical: Alter Aura, Death Trance, Impervious to Cold, Impervious to Fire, Levitation, Nightvision, Resist Fatigue, Resist Hunger, Resist Thirst, Summon Inner Strength. Super: Bio-Manipulation, Electrokinesis, Empathic Transmission, Hydrokinesis, Hypnotic Suggestion, Mentally Possess Others, Mind Bolt, Mind Bond, Mind Wipe, Psi-Shield, Psi-Sword, Pyrokinesis, Telekinesis (Super), Telekinetic Force Field. I.S.P. 240.', NULL, NULL, 'No weapons; he fights with his powers. Huntsman body armor (40 M.D.C.), grey shading to white.', NULL, 'An insane, calculating pleasure-seeker who needs to hurt people, and would rather it were villains and Splugorth Minions. With no enemy in reach he is a bomb waiting for innocents. Fiercely loyal to his friends, and unrepentant about a past he would not want them to learn.', 'Lyxander and Falcone, whom he will never harm', 'The Splugorth and their Minions', 'A criminal from a distant Atlantean colony who destroyed minds for pleasure, exiled to a prison asteroid, then taken by a Splugorth and sold as a slave. He escaped in Splynn and preyed on Minions until the Liberated Underground took him in; Lyxander keeps him close as a weapon. Thin, bald and nearly albino with pale pink eyes, he uses his unsettling looks to open a mental attack.', 'Rifts World Book 26: Dinosaur Swamp p.125-126'),
('zash-danzas', 'Zash-Danzas', NULL, 'Leader of the Sunaj Trackers', 'rifts', NULL, '10th level Sunaj Assassin', 10, 'Aberrant', 'Unknown; looks early 40s', '6 feet, 3 inches (1.9 m)', '193 lbs (86.8 kg)', '{"IQ":17,"ME":19,"MA":23,"PS":23,"PP":17,"PE":20,"PB":19,"Spd":35}', NULL, NULL, 107, 82, 71, NULL, NULL, '{"attacks":8,"initiative":3,"strike":2,"parry":6,"dodge":6,"damage":12,"roll":7,"pull":5,"entangle":2}', 'Hit Points and S.D.C. N/A: he is an M.D.C. being (107). Damage bonus is to S.D.C. damage. +3% I.Q. bonus on all skills. +2 to save vs psionics and insanity, +3 vs magic, +3 vs poison; 60% trust/intimidate, 45% charm/impress.', '[{"name":"Language: American","pct":98},{"name":"Language: Atlantean/Greek","pct":98},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Euro","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Disguise","pct":93},{"name":"Prowl","pct":88},{"name":"Pilot Jet Pack","pct":98},{"name":"Pilot Motorcycle","pct":98},{"name":"Pilot Space Fighter","pct":90},{"name":"Pilot Robots & Power Armor","pct":96}]', 'Hand to Hand: Assassin, Boxing, W.P. Archery & Targeting, W.P. Blunt, W.P. Sword, W.P. Energy Rifle, W.P. Energy Pistol, W.P. Paired, W.P. Whip.', 'Those of every Sunaj Assassin (Rifts World Book Two: Atlantis p.66): Tattoo Magic, M.D.C. transformation and the rest.', 'Marks of Heritage, his sword tattoo a broad scimitar. Further magic tattoos: a flaming staff, Death Touch, Black Sun, Heart of Steel, Eyes: Three, Eye of Knowledge, Heart with Large Wings, Heart Encircled by Chains, Skull Engulfed in Flames, Chain with Broken Link, Lightning Bolts.', 'Deaden Senses, Ectoplasmic Disguise, Telekinesis, Mind Block, Mask I.S.P. and Psionics, Object Read. I.S.P. 71.', NULL, NULL, 'Out of cover, Sunaj Assassin Environmental Armor (110 M.D.C.): black with faint deep-red trim, a knee-length cape, a false white ponytail, and a close-fitting mask with rows of small spikes, no mouthpiece and deep red lenses. Undercover, a pre-distressed or battle-damaged suit from a collection taken off past targets. Usual weapons out of cover: GR-10P Pistol (gravitonic), TW Starfire Pistol, Whip of Pain. The G.M. may add almost anything, Phase World and Naruni weapons included.', NULL, 'Charming when he chooses to be, which few see. Wholly devoted to his clan, he keeps his feelings apart from the job and works without mercy.', 'His Sunaj Trackers: the Sunaj Assassins Zandra and Zharon, the Kittani Espionage Agent Rell, the Mind Bleeder Bunkar, and three Staphra Warlords', 'Lyxander and the Eleytherians, whom he is hunting; the Liberated Underground', 'A rising legend among the Sunaj, of unknown origin and training; even whether Zash-Danzas is his real name is unknown. Aliases: Ascalus, Adin and Ajax (he favours names beginning with A). As Ascalus he spent three years inside the Liberated Underground as Lyxander''s friend and second in command, then betrayed the Eleytherians'' first raid. He has tracked them to Dinosaur Swamp, and regrets that this time he must kill a man he liked.', 'Rifts World Book 26: Dinosaur Swamp p.126-127'),
('porter', 'Porter', 'Cavor Porter', 'Chief of the Kopar tribe', 'rifts', 'Human', '8th level Mystic', 8, 'Scrupulous for now, though his judgement is clouding; the G.M. may decide whether something supernatural, a possession or madness is behind it', '24', '5 feet, 8 inches (1.7 m)', '145 lbs (65 kg)', '{"IQ":21,"ME":15,"MA":21,"PS":10,"PP":8,"PE":21,"PB":9,"Spd":13}', 54, 24, NULL, 109, 60, NULL, NULL, '{"attacks":5,"strike":1,"parry":3,"dodge":3,"damage":2,"roll":3,"pull":2}', '+7% I.Q. bonus on all skills. +5 to save vs psionics, +3 vs insanity, +2 vs Horror Factor, +5 vs magic, +3 vs poison; +2 to Spell Strength. M.D.C. by body armor only.', '[{"name":"Language: American","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Euro","pct":98},{"name":"Holistic Medicine","pct":72},{"name":"Play Musical Instrument: Harmonica and Guitar","pct":87}]', 'Athletics, Hand to Hand: Basic, W.P. Automatic Pistol.', 'None beyond a human''s; his magic and psionics are the Mystic O.C.C.''s (Rifts RPG).', 'Aura of Power (4), Cleanse (6), Create Wood (10+), Cure Minor Disorders (10), Cure Illness (15), Extinguish Fire (4), Globe of Daylight (2), Greater Healing (30), Lantern Light (1), Life Blast (15), Light Healing (6), Locate (30), Magic Net (7), Metamorphosis: Animal (25), Multiple Image (7), Mystic Alarm (5), Negate Poisons/Toxins (5), Purification (20), Repel Animals (7), Seal (7), Sustain (12), Turn Dead (6), Tongues (12). P.P.E. 109.', 'Clairvoyance, Exorcism, Sixth Sense, Commune with Spirits, Astral Projection, See the Invisible, Deaden Pain, Suppress Fear, Group Mind Block. I.S.P. 60.', NULL, NULL, 'The breastplate of a suit of Triax Explorer armor (35 M.D.C.), traded for years ago and painted in brown and green camouflage; a TX-5 Triax Pump Pistol in a shoulder holster; utility trousers, a green fatigue shirt and a dark green hooded cloak; a harmonica in his pocket and a guitar on his back.', NULL, 'Open, honest and generous, he leads by example and looks for the least violent answer, which has led some traders and adventurers to think him soft, to their cost. Privately he is hardening himself for the war with the Rat Men he believes is coming.', 'The Kopar barbarians and their Mystics', 'The Rat Men of Atlanta; possibly the True Atlanteans in the tunnels, whom he does not yet understand', 'A gifted Mystic from age three who became the Kopar''s spiritual chief at seventeen and has brought the tribe good years. He fears the tribe is outgrowing its food and that the Rat Men must be driven out to keep the Great Kopar''s favour. A lean young black man with a shaven head and a broad smile.', 'Rifts World Book 26: Dinosaur Swamp p.128-129'),
('pennent', 'Pennent', 'Pennent Larellen', 'Co-founder of Fort Hawkins', 'rifts', 'Elf', '10th level Wilderness Scout', 10, 'Scrupulous', '353 (looks late fifties)', '6 feet, 2 inches (1.8 m)', '170 lbs (77 kg)', '{"IQ":12,"ME":26,"MA":8,"PS":12,"PP":17,"PE":19,"PB":23,"Spd":15}', 42, 54, NULL, 11, NULL, NULL, NULL, '{"attacks":6,"strike":2,"parry":3,"dodge":3,"damage":2,"roll":3,"pull":2}', '+1 action with a bow. +2 to save vs Horror Factor, +6 vs psionics, +9 vs insanity, +2 vs magic, +2 vs poison; 65% charm/impress. M.D.C. by body armor. Occupation: teacher of fighting and wilderness skills.', '[{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: American","pct":98},{"name":"Sign Language","pct":98},{"name":"Lore: Religion","pct":98}]', 'Every Wilderness skill at 95%. Hand to Hand: Basic, W.P. Archery, W.P. Sword, W.P. Energy Pistol, W.P. Energy Rifle.', 'Nightvision 90 feet (27.4 m), even in total darkness; one extra archery attack per melee round.', 'None.', 'None.', NULL, NULL, 'A sampling, which the G.M. may change: enchanted chain mail with no weight and no sound (165 M.D.C.); a long sword with a copper-coloured blade (4D6 M.D.) that also fires bolts of flame (4D6 M.D., 300 feet/91.5 m); a hunting bow that doubles an arrow''s range; a gem whose inner light always points north; an Amulet of Invisibility; magic boots that leave no tracks; and a C-14 Fire Breather Assault Rifle he carries everywhere, with six spare E-Clips and 96 grenades.', NULL, 'Quiet and careful in what he says, he tends to answer a question with another to learn what the asker already knows. Age has made him spiritual and reflective.', 'Gran, his lifelong companion; his wife Elthrain; the apprentices and graduates of Fort Hawkins', 'Whatever dangerous thing comes through the Ocmulgee mound Rifts', 'An Elf from another world, taught ranger craft by his aunt P''quell, who left his village with Gran to wander the Megaverse for two centuries before settling in Dinosaur Swamp fifty years ago. With Gran he founded Fort Hawkins, trains apprentices there, and guards the Ocmulgee mound ley line network. Tall and thin, his long black hair greying.', 'Rifts World Book 26: Dinosaur Swamp p.131'),
('gran', 'Gran', 'Gran Anu', 'Co-founder of Fort Hawkins', 'rifts', 'Elf', '11th level Elven Palladium Long Bowman', 11, 'Unprincipled', '349', '6 feet, 3 inches (1.9 m)', '184 lbs (83 kg)', '{"IQ":20,"ME":12,"MA":9,"PS":13,"PP":23,"PE":13,"PB":21,"Spd":28}', 50, 60, NULL, 14, NULL, NULL, NULL, '{"attacks":6,"strike":6,"parry":8,"dodge":8,"damage":3,"roll":3,"pull":2}', 'Six hand to hand attacks per round, or ten with a longbow, at a range of 950 feet (289.6 m). +6% I.Q. bonus on all skills; 55% charm/impress. M.D.C. by body armor only. Occupation: teacher of fighting and wilderness skills.', '[{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Language: American","pct":98},{"name":"Basic Math","pct":98},{"name":"Literacy: Dragonese","pct":98},{"name":"Literacy: American","pct":98},{"name":"Lore: D-Bee","pct":81},{"name":"Law (General)","pct":81},{"name":"Sign Language","pct":98},{"name":"Writing","pct":81}]', 'Sniper; most Wilderness skills at 90-98%. Hand to Hand: Expert, W.P. Longbow, W.P. Sword, W.P. Blunt.', 'Nightvision 90 feet (27.4 m), even in total darkness; one extra archery attack per melee round.', 'None.', 'None.', NULL, NULL, 'A sampling, which the G.M. may change: an enchanted leather breastplate, light and silent (79 M.D.C. left); a plain longbow, his pride, with S.D.C., M.D. and magic arrows including SteelTree arrows (SteelTree Forged Weapon: Arrow, Broadhead and Arrow, Target Head) and tech-arrows, and usually several dozen Arrowhead: Neural Disrupter; an enchanted waterskin that becomes a long sword (4D6 M.D.) on command; a Cloak of Invisibility; an amulet that casts Diminish (Self). He will not use firearms or any other projectile weapon.', NULL, 'Quick with a sharp remark and hot-tempered about his opinions, he loves an argument as long as he wins it. Proud enough of his archery that he refuses every other ranged weapon.', 'Pennent, his lifelong companion; his wife Sheilaina, an Elven Techno-Wizard of Lazlo, and their son Gran the Second; the people of Fort Hawkins', 'The Coalition States, whose censorship he has fought in print and in person', 'An Elf from Pennent''s village, a gifted longbow teacher in his thirties and a troublemaker who chafed at his elders. Travelling with Pennent he came to love books, writes his own, and became a pamphleteer against the Coalition admired in Lazlo. He co-founded Fort Hawkins and teaches survival as a frame of mind. Blond and sharp-featured, in a leather cuirass over a green quilted tunic.', 'Rifts World Book 26: Dinosaur Swamp p.131-132');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 9 notable NPCs are in' AS assertion, count(*) AS got, 9 AS want
  FROM notable_npcs WHERE slug IN ('tunnel-goblin-leader', 'hirgg', 'lyxander', 'falcone', 'oxrik', 'zash-danzas', 'porter', 'pennent', 'gran');
SELECT 'and the notables 0' AS assertion, count(*) AS got, 0 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('tunnel-goblin-leader', 'hirgg', 'lyxander', 'falcone', 'oxrik', 'zash-danzas', 'porter', 'pennent', 'gran');

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~252-dinosaur-swamp-npcs.sql');
